169	/* Tooltip system */
170	.tooltip {
171	  display: inline-block;
172	}
173	
174	.tooltip::after {
175	  content: attr(data-tooltip);
176	  position: absolute;
177	  bottom: 80%;
178	  left: 50%;
179	  transform: translateX(-50%);
180	  background: #082753;
181	  color: #fff;
182	  padding: 8px 12px;
183	  border-radius: 6px;
184	  font-size: 12px;
185	  white-space: normal;
186	  opacity: 0;
187	  pointer-events: none;
188	  transition: 0.25s ease;
189	  z-index: 9999;
190	  width: 200px;
191	  text-align: center;
192	}
193	
194	.tooltip:hover::after {
195	  opacity: 1;
196	  bottom: 90%;
197	}
198	
199	.tooltip::before {
200	  content: '';
201	  position: absolute;
202	  bottom: 71%;
203	  left: 50%;
204	  transform: translateX(-50%);
205	  border: 6px solid transparent;
206	  border-top-color: #082753;
207	  opacity: 0;
208	  transition: 0.25s ease;
209	}
210	
211	@media screen and (max-width: 480px) {
