3	import { useState, useEffect } from "react";
4	
5	export function useMediaQuery(query: string): boolean {
6	  const [matches, setMatches] = useState(false);
7	
8	  useEffect(() => {
9	    const mql = window.matchMedia(query);
10	    setMatches(mql.matches);
11	
12	    function handler(e: MediaQueryListEvent) {
13	      setMatches(e.matches);
14	    }
15	
16	    mql.addEventListener("change", handler);
17	    return () => mql.removeEventListener("change", handler);
18	  }, [query]);
19	
20	  return matches;
21	}
